class Solution {
public:
    vector<int> findOriginalArray(vector<int>& changed){
        int n=changed.size();if(n%2)return {};
        sort(changed.begin(),changed.end());unordered_map<int,int>cnt;
        for(int x:changed)++cnt[x];vector<int>ans;
        for(int x:changed){if(cnt[x]==0)continue;
            if(cnt[2*x]==0||(x==0&&cnt[x]<2))return {};
            --cnt[x];--cnt[2*x];ans.push_back(x);
        }
        return (int)ans.size()==n/2?ans:vector<int>{};
    }
};
